const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Washington D.C.
  const dc = ee.Geometry.Point([-77.0369, 38.9072]);

  // 2. Define dates
  const date1 = '2019-01-29';
  const date2 = '2019-02-05';

  // 3. Get ERA5-Land daily temperature data
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGREGATED');

  // Get image for January 29
  const img1 = era5.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const size1 = era5.filterDate(date1, ee.Date(date1).advance(1, 'day')).size().getInfo();

  // Get image for February 5
  const img2 = era5.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();
  const size2 = era5.filterDate(date2, ee.Date(date2).advance(1, 'day')).size().getInfo();

  console.log(`Images found - Jan 29: ${size1}, Feb 5: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Extract temperature values (in Kelvin, convert to Celsius)
  // temperature_2m is in Kelvin, subtract 273.15 to get Celsius
  const temp1_dict = img1.select('temperature_2m').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dc,
    scale: 10000,
    maxPixels: 1e9
  });

  const temp2_dict = img2.select('temperature_2m').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dc,
    scale: 10000,
    maxPixels: 1e9
  });

  const temp1_k = temp1_dict.get('temperature_2m').getInfo();
  const temp2_k = temp2_dict.get('temperature_2m').getInfo();

  // Check for null values
  if (temp1_k === null || temp2_k === null) {
    console.log('Temperature calculation failed - null values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to Celsius
  const temp1_c = temp1_k - 273.15;
  const temp2_c = temp2_k - 273.15;

  // Validate temperature range (-100 to 100°C is reasonable)
  if (temp1_c < -100 || temp1_c > 100 || temp2_c < -100 || temp2_c > 100) {
    console.log(`Invalid temperature values: ${temp1_c.toFixed(2)}°C, ${temp2_c.toFixed(2)}°C`);
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate absolute difference
  const temp_diff = Math.abs(temp1_c - temp2_c);

  // 5. Print results and determine answer
  console.log(`Jan 29, 2019: ${temp1_c.toFixed(2)}°C`);
  console.log(`Feb 5, 2019: ${temp2_c.toFixed(2)}°C`);
  console.log(`Temperature difference: ${temp_diff.toFixed(2)}°C`);

  if (temp_diff >= 24) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
